```tsx
import React, { useReducer } from 'react';
import { Container, Header, Button, Textarea } from '@cloudscape-design/components';
import { sendReply } from '../api/tickets';

type S = { subject: string; body: string; errors: Record<string, string> };
type A =
  | { type: 'set'; field: 'subject' | 'body'; value: string }
  | { type: 'errors'; errors: Record<string, string> };

function reducer(s: S, a: A): S {
  if (a.type === 'set') return { ...s, [a.field]: a.value };
  return { ...s, errors: a.errors };
}

export function ReplyForm({ ticketId }: { ticketId: string }) {
  const [s, dispatch] = useReducer(reducer, { subject: '', body: '', errors: {} });

  const submit = async () => {
    const errors: Record<string, string> = {};
    if (!s.subject.trim()) errors.subject = 'Subject is required';
    if (s.body.length < 10) errors.body = 'Reply must be at least 10 characters';
    if (s.body.length > 2000) errors.body = 'Reply is too long';
    dispatch({ type: 'errors', errors });
    if (Object.keys(errors).length) return;
    await sendReply(ticketId, { subject: s.subject, body: s.body });
  };

  return (
    <Container>
      <input
        className="reply-subject"
        value={s.subject}
        onChange={(e) => dispatch({ type: 'set', field: 'subject', value: e.target.value })}
      />
      <Textarea value={s.body} onChange={({ detail }) => dispatch({ type: 'set', field: 'body', value: detail.value })} />
      <Button variant="primary" onClick={submit}>Send reply</Button>
    </Container>
  );
}
```

