```tsx
import { Table, Header, Box, Link } from '@cloudscape-design/components';

export interface DeployRow {
  id: string;
  at: string;
  actor?: { name: string };
  state: 'succeeded' | 'failed' | 'rolled_back';
}

// vendor payloads differ a bit so keep it loose
const formatRow = (row: any) => ({
  id: row.id,
  when: new Date(row.at).toLocaleString(),
  who: row.actor?.name ?? 'system',
  status: row.state,
});

export function DeployHistory({ rows }: { rows: DeployRow[] }) {
  const items = rows.map(formatRow);
  return (
    <Table
      header={<Header counter={`(${items.length})`}>Deploy history</Header>}
      items={items}
      empty={<Box textAlign="center">No deploys yet</Box>}
      columnDefinitions={[
        { id: 'when', header: 'When', cell: (i) => i.when },
        { id: 'who', header: 'Who', cell: (i) => i.who },
        { id: 'status', header: 'Status', cell: (i) => i.status },
      ]}
    />
  );
}
```

