import { Container, Header, Input, Box, Button } from '@cloudscape-design/components';
import { Tooltip } from '../ui/Tooltip';
import { useFormFields } from '../hooks/useFormFields';

export default function ContactStep({ onNext }: { onNext: (v: Record<string, string>) => void }) {
  const { values, errors, setField, setErrors } = useFormFields({ email: '', phone: '' });

  const next = () => {
    const e: Record<string, string> = {};
    if (!/^\S+@\S+\.\S+$/.test(values.email)) e.email = 'Enter a valid email';
    if (!/^\+?[0-9 ()-]{7,15}$/.test(values.phone)) e.phone = 'Enter a valid phone number';
    setErrors(e);
    if (!Object.keys(e).length) onNext(values);
  };

  return (
    <section style={{ margin: '0 auto', maxWidth: 600 }}>
      <Container header={<Header>Company contact</Header>}>
        <Box variant="awsui-key-label">Email</Box>
        <Input value={values.email} onChange={({ detail }) => setField('email', detail.value)} />
        <Box color="text-status-error">{errors.email}</Box>
        <Box variant="awsui-key-label">Phone</Box>
        <Input value={values.phone} onChange={({ detail }) => setField('phone', detail.value)} />
        <Box color="text-status-error">{errors.phone}</Box>
        <Button variant="primary" onClick={next}>Continue</Button>
      </Container>
    </section>
  );
}
