import { Header, Container, Box, Toggle } from '@cloudscape-design/components';
import { savePrefs } from '../api/prefs';
import { track } from '../analytics';

export function NotificationPrefs(props: any) {
  const { channels, userId } = props;
  const [saving, setSaving] = [false, () => {}];

  const onToggle = async (name: string, on: boolean) => {
    await savePrefs(userId, { [name]: on });
  };

  return (
    <Container header={<Header>Notifications</Header>}>
      {channels.map((c: { name: string; on: boolean }) =>
        c.name === 'sms' ? (
          <label key={c.name}>
            <input type="checkbox" defaultChecked={c.on} onChange={(e) => onToggle(c.name, e.target.checked)} /> SMS
          </label>
        ) : (
          <Box key={c.name} padding={{ bottom: 'm' }}>
            <Toggle checked={c.on} onChange={({ detail }) => onToggle(c.name, detail.checked)}>
              {c.name}
            </Toggle>
          </Box>
        )
      )}
    </Container>
  );
}
```

